def unit_of_work(metadata=None, timeout=None):
    @wraps(unit_of_work)
    def wrapper(function):
        @wraps(function)
        def wrapped(*args, **kwargs):
            tx = neo4j.transaction.Transaction(function.__name__, metadata, timeout)
            try:
                tx.begin()
