def parse_version(s: str) -> tuple[int, ...]:
    """
    Parse the given string as a version number and return a tuple of integers representing the version components.
    The version number should be in the format "X.Y.Z", where X, Y, and Z are integers.
    """
    if not s:
        raise ValueError("Empty string")

    version_components = s.split(".")
    if len(version_components) != 3:
        raise ValueError(f"Invalid format: '{s}'")

    version_parts = []
    for part in version_components:
        try:
            version_parts.append(int(part))
        except ValueError:
            raise ValueError(f"Invalid version component: '{part}'")

    return tuple(version_parts)

