def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    min_key = None
    for key, _ in self.items():
        if min_key is None or key < min_key:
            min_key = key

    value = self[min_key]
    del self[min_key]
    return (min_key, value)

