    if not isinstance(e, Exception):
        raise ValueError("e must be an exception instance")
    if not isinstance(max_level, int):
        raise ValueError("max_level must be an integer")
    if not isinstance(max_path_level, int):
        raise ValueError("max_path_level must be an integer")
    if max_level < 1:
        raise ValueError("max_level must be at least 1")
    if max_path_level < 1:
        raise ValueError("max_path_level must be at least 1")

    # Build the exception string
    estr = f"{e.__class__.__name__}: {str(e)}\n"
    for i, (frame, line) in enumerate(traceback.walk_tb(e.__traceback__)):
        if i == max_level:
            estr += f"... (traceback truncated at level {max_level})\n"
            break
        estr += f"  File {frame.f_code.co_filename}, line {line}, in {frame.f_code.co_name}\n"
        for j, (path, lineno) in enumerate(traceback.walk_tb(frame.f_trace)):
            if j == max_path_level:
                estr += f"    ... (traceback truncated at level {max_path_level})\n"
                break
            estr += f"      File {path}, line {lineno}, in ??\n"
