def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not (bins and edges):
        raise ValueError("bins and edges must not be empty")

    if not (len(bins) == len(edges) - 1):
        raise ValueError("bins and edges must have the same length")

    if any(bin < 0 or bin > 1 for bin in bins):
        raise ValueError("bins values must be between 0 and 1")

    if any(edge < 0 for edge in edges):
        raise ValueError("edges values must be greater or equal to 0")

    if edges[0] != 0:
        raise ValueError("first edge value must be 0")

    if edges[-1] != 1:
        raise ValueError("last edge value must be 1")

    integral = 0
    for i in range(len(bins)):
        integral += bins[i] * (edges[i + 1] - edges[i])

    return integral

