    d1 = d1.copy()
    d2 = d2.copy()
    for k, v in d2.items():
        if k in d1:
            if hash(v) != hash(d1[k]):
                if isinstance(v, dict) and isinstance(d1[k], dict):
                    d1[k] = difference(v, d1[k], level - 1)
                elif not isinstance(v, dict) and not isinstance(d1[k], dict):
