def _difference_limited(d1, d2, level):
    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = value
        elif level > 0 and isinstance(value, dict) and isinstance(d2[key], dict):
            result[key] = _difference_limited(value, d2[key], level - 1)
        else:
            if value != d2[key]:
                result[key] = value
    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Check if d1 and d2 are valid dictionaries
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("d1 and d2 must be dictionaries.")

    # Create a copy of d1
    result = d1.copy()

    # If level is set to -1, recurse infinitely
    if level == -1:
        for key, value in d2.items():
            if key in result:
                result[key] = difference(result[key], value, level)
            else:
                result[key] = value
    # If level is set to some positive integer, recurse to that level
    else:
        for key, value in d2.items():
            if key in result:
                result[key] = difference(result[key], value, level - 1)
            else:
                result[key] = value

    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple):
        raise TypeError("Coordinate must be a tuple")
    if not len(coord) == self.ndim:
        raise ValueError("Coordinate must have same dimension as histogram")
    if any(not 0 <= c < self.shape[i] for i, c in enumerate(coord)):
        return
    key = self.coord_to_key(coord)
    if key not in self.data:
        self.data[key] = 0
    self.data[key] += weight

def _validate_labels(labels):
    def _is_valid_label_key(key):
        try:
            # Check if the label key is a string
            if not isinstance(key, str):
                raise ValueError("Label key '{}' does not match the regex [...]".format(key))
            # Check if the label key matches the regex
            elif not re.match(r"[a-z][a-z0-9_]*", key):
                raise ValueError("Label key '{}' does not match the regex [...]".format(key))
            else:
                return True
        except ValueError as e:
            return {"{}".format(key): e.args[0]}

    def _is_valid_label_value(value):
        try:
            # Check if the label value is a string
            if not isinstance(value, str):
                raise ValueError("Label value '{}' does not match the regex [...]".format(value))
            # Check if the label value matches the regex
            elif not re.match(r"[a-z][a-z0-9_]*", value):
                raise ValueError("Label value '{}' does not match the regex [...]".format(value))
            else:
                return True
        except ValueError as e:
            return {"{}".format(value): e.args[0]}

    errors = []
    for key, value in labels.items():
        # Check if the label key is valid
        if not _is_valid_label_key(key):
            errors.append(_is_valid_label_key(key))
        # Check if the label value is valid
        if not _is_valid_label_value(value):
            errors.append(_is_valid_label_value(value))

    if len(errors) > 0:
        raise ValidationError(errors)

