def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """

    def _generate_default_observer_schema_dict(manifest_dict):
        if not isinstance(manifest_dict, dict):
            raise TypeError("manifest_dict must be a dict, but got {}".format(type(manifest_dict)))
        observer_schema = {}
        for key, value in manifest_dict.items():
            if isinstance(value, list) or isinstance(value, dict):
                observer_schema[key] = _generate_default_observer_schema_dict(value)
            else:
                observer_schema[key] = None
        return observer_schema

    return _generate_default_observer_schema_dict(manifest_dict)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """ Generate the default observer schema dictionary from the provided manifest dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resource manifest.
        first_level (bool, optional): Flag indicating first-level dictionary.

    Returns:
        dict: Generated partial observer_schema.

    Raises:
        ValueError: If manifest_dict is not a dictionary.
    """

    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    # Create a new dictionary by copying the keys and sub-dictionaries from the manifest dict
    result = {
        key: generate_default_observer_schema_dict(value)
        for key, value in manifest_dict.items()
        if isinstance(value, dict)
    }

    if first_level:
        # In case of first-level dictionary, copy the identifying field values
        for key, value in manifest_dict.items():
            if isinstance(value, dict):
                for sub_key in value.keys():
                    result[key][sub_key] = sub_key in manifest_dict[key]

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """ Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    Raises:
        ValueError: If ``manifest_dict`` is not a dictionary
        ValueError: If ``first_level`` is not a boolean
    """

    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    if not isinstance(first_level, bool):
        raise ValueError("first_level must be a boolean")

    result = {}

    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            result[key] = generate_default_observer_schema_list(value, first_level=False)
        else:
            result[key] = None

    if first_level:
        result["metadata"] = {"labels": manifest_dict.get("labels", {})}
        result["spec"] = manifest_dict.get("spec", {})
        result["status"] = manifest_dict.get("status", {})

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
