        if isinstance(value, dict):
            result_dict[key] = value
        elif isinstance(value, list):
            result_dict[key] = value
        else:
            result_dict[key] = None

    if first_level:
        result_dict["name"] = manifest_dict.get("name")
        result_dict["namespace"] = manifest_dict.get("namespace")
