):
    for i in range(len(observer_schema)):
        if observer_schema[i] == "dict":
            last_applied_manifest[i] = update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[i], observer_schema[i], response[i]
            )
        elif observer_schema[i] == "list":
            last_applied_manifest[i] = update_last_applied_manifest_list_from_resp(
                last_applied_manifest[i], observer_schema[i], response[i]
            )
        else:
