def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    * sql (:class:`str` or :class:`bytes`) is the SQL query.
    * params (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style, then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    - The formatted SQL query (:class:`str` or :class:`bytes`).
    - The set of converted out-style parameters (:class:`dict` or
    :class:`list`).
    """
    if self.in_style == NamedStyle.NAMED:
        pass
    elif self.in_style == NamedStyle.FORMAT:
        pass
    elif self.in_style == NamedStyle.PYFORMAT:
        pass
    elif self.in_style == NamedStyle.QMARK:
        pass
    else:
        raise ValueError(f"Unsupported in-style: {self.in_style}")

    if self.out_style == NamedStyle.NAMED:
        pass
    elif self.out_style == NamedStyle.FORMAT:
        pass
    elif self.out_style == NamedStyle.PYFORMAT:
        pass
    elif self.out_style == NamedStyle.QMARK:
        pass
    else:
        raise ValueError(f"Unsupported out-style: {self.out_style}")

def formatmany(sql, many_params: List[Dict[Union[str, int], Any]]) -> Tuple[AnyStr, List[Dict[Union[str, int], Any]]]:

    formatted_sql = ""
    out_style_params = []
    for params in many_params:
        # check if params is a dict
        if isinstance(params, dict):
            # check if any param value is a list
            for param_value in params.values():
                if isinstance(param_value, list):
                    raise ValueError("Param values cannot be lists when using named parameter style")

            # convert to out-style parameters
            out_style_params.append({k: v for k, v in params.items()})
        # check if params is a sequence
        elif isinstance(params, Iterable):
            # check if any param is a dict
            for param in params:
                if isinstance(param, dict):
                    raise ValueError("Param values cannot be dicts when using ordinal parameter style")

            # convert to out-style parameters
            out_style_params.append(list(params))
        else:
            raise TypeError(f"Invalid params type {type(params).__name__}, must be a dict or sequence")

        # format the SQL query
        formatted_sql = sql.format(**params)

    return formatted_sql, out_style_params

