def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        try:
            spec_version = inventory.get("type").get("spec")
        except AttributeError:
            spec_version = None
        if spec_version is None:
            spec_version = self.spec_version
    else:
        spec_version = self.spec_version
    if not isinstance(inventory, self.spec_version.inventory_type):
        raise TypeError(f"Invalid inventory type: {type(inventory)}")
    if not isinstance(inventory.get("type"), self.spec_version.inventory_type):
        raise TypeError(f"Invalid inventory type: {type(inventory.get('type'))}")
    if not isinstance(inventory.get("spec"), self.spec_version.spec_type):
        raise TypeError(f"Invalid spec type: {type(inventory.get('spec'))}")
    if not isinstance(inventory.get("components"), dict):
        raise TypeError(f"Invalid components type: {type(inventory.get('components'))}")
    for component_name, component in inventory.get("components").items():
        if not isinstance(component, self.spec_version.component_type):
            raise TypeError(f"Invalid component type: {type(component)}")
        if not isinstance(component.get("name"), str):
