def _explore_zipfile(zip_path):
    import zipfile
    import xml.etree.ElementTree as ET

    with zipfile.ZipFile(zip_path) as zf:
        ns = "{http://schemas.microsoft.com/packaging/2010/07/nuspec.xsd}"
        packages = {}
        for name in zf.namelist():
            if not name.endswith(".nuspec"):
                continue
            with zf.open(name) as nuspec:
                tree = ET.parse(nuspec)
                root = tree.getroot()
                basename = root.find(f".//{ns}metadata/{ns}id").text
                packages[basename] = {}
                for child in root:
                    if child.tag == f"{ns}metadata":
                        for grandchild in child:
                            if grandchild.tag == f"{ns}version":
                                packages[basename]["version"] = grandchild.text
                            if grandchild.tag == f"{ns}dependencies":
                                for dep in grandchild:
                                    packages[basename].setdefault("dependencies", []).append(
                                        (dep.attrib["id"], dep.attrib["version"])
                                    )

    return packages

