def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not args:
        args = []
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ.copy()
    if isinstance(env, dict):
        env = {**os.environ, **env}
    else:
        raise TypeError("Invalid environment, must be a dictionary")
    for command in commands:
        try:
            if verbose:
                click.echo("Running command: {}".format(command))
            process = subprocess.Popen(command, cwd=cwd, env=env, stdin=subprocess.PIPE,
                                    stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            outs, errs = process.communicate(input=args, timeout=10)
            if process.returncode != 0:
                if not hide_stderr:
                    if errs:
                        click.echo(errs.decode("utf-8"), err=True)
                    else:
                        click.echo("Error: {} returned exit status {}".format(command, process.returncode), err=True)
                else:
                    raise RuntimeError("Error: {} returned exit status {}".format(command, process.returncode))
            if outs:
                if verbose:
                    click.echo(outs.decode("utf-8"))
                return outs.decode("utf-8")
        except subprocess.TimeoutExpired:
            process.kill()
            outs, errs = process.communicate()
            if not hide_stderr:
                click.echo("Error: {} timed out after 10 seconds".format(command), err=True)
            else:
                raise RuntimeError("Error: {} timed out after 10 seconds".format(command))

