def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    for file_name in os.listdir(self.root_dir):
        file_path = os.path.join(self.root_dir, file_name)
        if not os.path.isdir(file_path):
            continue

        for object_name in os.listdir(file_path):
            object_path = os.path.join(file_path, object_name)
            if not os.path.isfile(object_path):
                continue

            num_objects += 1
            if validate_objects and not self.validate_object(object_path):
                if show_warnings:
                    print(f"WARNING: object at {object_path} failed validation")
                continue

            if check_digests and not self.check_digest(object_path):
                if show_warnings:
                    print(f"WARNING: digest for object at {object_path} does not match")
                continue

            good_objects += 1

    return num_objects, good_objects

