        raise ValueError("Invalid input: version must be a string")

    # Split version into parts
    parts = version.split(".")

    # Check if zero-prefixed
    zero_prefixed = parts[0].startswith("0")

    # Increment last part
    last_part = parts[-1]
    try:
        last_part = str(int(last_part) + 1)
    except ValueError:
        raise ValueError("Invalid version part: must be an integer")

    # Add prefix if necessary
    if zero_prefixed and len(last_part) < 2:
        last_part = "0" + last_part

    # Join parts
    parts[-1] = last_part
    return ".".join(parts)

