def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_arguments = {}
    remaining_arguments = []

    for subparser, parser in subparsers.items():
        try:
            parsed_arguments[subparser] = parser.parse_known_args(unparsed_arguments)
        except ArgumentError:
            print(f"Failed to parse arguments with subparser {subparser}")
            raise
        else:
            remaining_arguments.extend(parsed_arguments[subparser].extraneous)

    return (parsed_arguments, remaining_arguments)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_arguments = {}
    remaining_arguments = []
    for subparser_name, subparser in subparsers.items():
        try:
            parsed_arguments[subparser_name] = subparser.parse_args(unparsed_arguments)
        except ArgumentError:
            continue
    for argument in unparsed_arguments:
        if not any(argument in subparser.options for subparser in subparsers.values()):
            remaining_arguments.append(argument)
    return parsed_arguments, remaining_arguments

def paging(response, max_results):
    if not isinstance(response, list):
        raise ValueError("'response' must be a list")
    if not isinstance(max_results, int):
        raise ValueError("'max_results' must be a positive integer")
    if max_results < 1:
        raise ValueError("'max_results' must be a positive integer")

    page = 0
    while page * max_results < len(response):
        yield response[page * max_results:(page + 1) * max_results]
        page += 1

def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.upper()
        if size.endswith("KB"):
            return int(size[:-2]) * 1000
        elif size.endswith("MB"):
            return int(size[:-2]) * 1000000
        elif size.endswith("GB"):
            return int(size[:-2]) * 1000000000
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size value")

