def vertex_3tuple(vertices):
    """
    Return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex.

    :param vertices: The list of vertices of the polygon.
    :return: A list of 3-tuples, where each tuple contains the vertex and the 2 points on both sides of the vertex.
    """
    # Check if the input is valid
    if not isinstance(vertices, list) or not all(isinstance(vertex, tuple) for vertex in vertices):
        raise ValueError("The input must be a list of tuples.")

    # Define a function to return the 2 points on both sides of a vertex
    def get_side_points(vertex):
        i = vertices.index(vertex)
        if i == 0:
            return vertices[-1], vertices[1]
        elif i == len(vertices) - 1:
            return vertices[i - 1], vertices[0]
        else:
            return vertices[i - 1], vertices[i + 1]

    # Generate the 3-tuples
    return [get_side_points(vertex) + (vertex,) for vertex in vertices]

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("Input must be an integer")
    if not isinstance(alphabet, list):
        raise ValueError("Alphabet must be a list of strings")
    if not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must contain only strings")

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None and len(result) < padding:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of strings")
    if not all(isinstance(char, str) for char in alphabet):
        raise TypeError("alphabet must contain only strings")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("padding must be a non-negative integer")

    base = len(alphabet)
    if base == 0:
        raise ValueError("alphabet must contain at least one character")
    if number == 0:
        return alphabet[0]

    digits = []
    while number:
        number, remainder = divmod(number, base)
        digits.append(alphabet[remainder])

    if padding:
        num_digits = len(digits)
        if num_digits < padding:
            digits = [alphabet[0]] * (padding - num_digits) + digits

    return "".join(reversed(digits))

