def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    import re

    if platform == 'this':
        platform = '1' if sys.platform.startswith('linux') else '0'

    pattern = re.compile(r'''(?x)
        \s*(?:
            # double quotes
            "(?P<dquote>[^"]*(?:"[^\\"]*(?:\\.[^"]*)*))" |

            # single quotes
            '(?P<quote>[^']*(?:''[^\\']*(?:\\.[^']*)*))' |

            # unquoted
            (?P<unquoted>[^'"\s]+(?:\S*(?:\S*(?:\S*(?:(?<!\\)[^'"\s]))))*)
        )
        ''', re.VERBOSE)

    result = []

    for match in pattern.finditer(s):
        if match.group('dquote'):
            result.append(match.group('dquote').replace('\\"', '"'))
        elif match.group('quote'):
            result.append(match.group('quote').replace("''", "'"))
        else:
            result.append(match.group('unquoted'))

    return result

