        raise ValueError("No configuration files provided")

    results = {}
    errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as f:
                config = yaml.safe_load(f)
        except IOError as e:
            errors.append(logging.LogRecord(logging.ERROR, config_filename, None, e))
            continue
        except yaml.YAMLError as e:
            errors.append(logging.LogRecord(logging.ERROR, config_filename, None, e))
            continue
        if overrides:
            for key, value in overrides.items():
                config[key] = value
        results[config_filename] = config

    if resolve_env:
        for config in results.values():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith("$env:"):
                    value = os.environ.get(value[5:])
                    if value is not None:
                        config[key] = value

    return results, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename) as f:
                config = yaml.safe_load(f)
                if overrides:
                    config = {**config, **overrides}
                if resolve_env:
                    config = resolve_environment_placeholders(config)
                validate_configuration(config)
                configs[filename] = config
        except IOError as e:
            error_records.append(logging.LogRecord(logging.ERROR, e))
        except ValidationError as e:
            error_records.append(logging.LogRecord(logging.ERROR, e))

    return configs, error_records

