@classmethod
def from_ticks(cls, ticks, tz=None):
    """Create a time from ticks (nanoseconds since midnight).

    :param ticks: nanoseconds since midnight
    :type ticks: int
    :param tz: optional timezone
    :type tz: datetime.tzinfo

    :rtype: Time

    :raises ValueError: if ticks is out of bounds
        (0 <= ticks < 86400000000000)
    """

    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

    hh = int(ticks / 1000000000) % 24
    mm = int(ticks / 1000000) % 60
    ss = int(ticks / 1000) % 60
    frac = ticks % 1000

    if tz is None:
        return Time(hour=hh, minute=mm, second=ss, microsecond=frac)
    else:
        return Time(hour=hh, minute=mm, second=ss, microsecond=frac, tzinfo=tz)

@classmethod
def from_ticks(cls, ticks, tz=None):
    """Create a time from ticks (nanoseconds since midnight).

    :param ticks: nanoseconds since midnight
    :type ticks: int
    :param tz: optional timezone
    :type tz: datetime.tzinfo

    :rtype: Time

    :raises ValueError: if ticks is out of bounds
        (0 <= ticks < 86400000000000)
    """
    if not (0 <= ticks < 86400000000000):
        raise ValueError(f"Ticks must be between 0 and 86400000000000, got {ticks}.")
    hour = ticks // 3600000000000
    minute = (ticks // 60000000000) % 60
    second = (ticks // 1000000000) % 60
    microsecond = (ticks // 1000) % 1000
    if tz is not None:
        return Time(hour, minute, second, microsecond, tz)
    else:
        return Time(hour, minute, second, microsecond)

@classmethod
def from_ticks(cls, ticks, tz=None):
    """Create a time from ticks (nanoseconds since midnight)."""
    # Step 1: Validate inputs
    if not isinstance(ticks, int):
        raise TypeError(f"ticks must be an int, got {type(ticks).__name__}")
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError(f"ticks must be within range [0, 86400000000000), got {ticks}")
    if tz is not None and not isinstance(tz, datetime.tzinfo):
        raise TypeError(f"tz must be a datetime.tzinfo, got {type(tz).__name__}")

    # Step 2: Create time object
    time_obj = Time(ticks, tz)

    # Step 3: Return time object
    return time_obj

