    """

    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError(f"Protocol version {protocol_version} must be passed as a tuple")

    handlers = {}

    if protocol_version is None:
        # Return all available handlers
        handlers = {(3, 5): Bolt3x5ProtocolHandler}
    else:
        # Return the specified handler, if it exists
        if protocol_version in {(3, 5)}:
            handlers = {protocol_version: Bolt3x5ProtocolHandler}

    return handlers

