    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: handler for version, handler in cls.VERSION_TO_HANDLER.items()}

    if not isinstance(protocol_version, tuple) or len(protocol_version) != 2:
        raise TypeError("protocol_version must be a tuple of length 2")

    version_string = ".".join(str(v) for v in protocol_version)

    if version_string not in cls.VERSION_TO_HANDLER:
        raise TypeError(f"Unsupported protocol version: {version_string}")

    return {protocol_version: cls.VERSION_TO_HANDLER[version_string]}

