def verify_relayable_signature(public_key, doc, signature):
    try:
        # Parse the XML document and extract the signatures
        xml_doc = parse_xml(doc)
        signatures = xml_doc.findall(".//ds:Signature", NAMESPACES)

        # Check if there are any signatures
        if not signatures:
            raise ValueError("No signatures found in the XML document")

        # Check if the public key is valid
        if not is_valid_public_key(public_key):
            raise ValueError("Invalid public key")

        # Verify the signature
        for signature in signatures:
            sig = signature.findall(".//ds:SignatureValue", NAMESPACES)
            if not sig or len(sig) != 1:
                raise ValueError("Invalid signature")
            sig_value = bytes(sig[0].text, "utf-8")
            if not public_key.verify(sig_value, doc.encode("utf-8")):
                raise ValueError("Invalid signature")

        # Check if the signature matches the public key
        if not public_key.verify(sig_value, doc.encode("utf-8")):
            raise ValueError("Signature does not match the public key")

        # Check if the signature is valid
        if not is_valid_signature(sig_value):
            raise ValueError("Invalid signature")

    except Exception as e:
        raise ValueError("Failed to verify relayable signature: " + str(e))

    return True

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
    except ImportError:
        raise ImportError("The 'json' module is required to parse Diaspora webfinger documents.")

    try:
        import xml.etree.ElementTree as ET
    except ImportError:
        raise ImportError("The 'xml.etree.ElementTree' module is required to parse Diaspora webfinger documents.")

    # Try to parse the document as JSON first
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        # If that fails, try to parse it as XRD
        try:
            tree = ET.fromstring(document)
            data = {}
            for node in tree.findall(".//XRD/Link"):
                property = node.attrib.get("property", None)
                if property:
                    data[property] = node.text
        except ET.ParseError:
            raise ValueError("The provided webfinger document is neither in JSON nor XRD format.")

    return data

def parse_diaspora_webfinger(document: str) -> Dict:
    if not document:
        raise ValueError("The document cannot be empty")

    try:
        data = json.loads(document)
        if not data or not isinstance(data, dict):
            raise ValueError("The document is not a valid JSON object")

        # Check if the document is in the new Diaspora format
        if "links" in data and isinstance(data["links"], list):
            for link in data["links"]:
                if link["rel"] == "http://webfinger.net/rel/profile-page":
                    return {
                        "username": link["href"].rsplit("/", 1)[1],
                        "handle": link["properties"]["https://diaspora.org/ns/handle"]
                    }
    except json.JSONDecodeError:
        # If the document is not in JSON format, try to parse it as XRD
        xrd = XRD(data)
        if not xrd:
            raise ValueError("The document is not a valid XRD object")

        # Extract the profile-page link from the XRD
        for link in xrd.links:
            if link.rel == "http://webfinger.net/rel/profile-page":
                return {
                    "username": link.href.rsplit("/", 1)[1],
                    "handle": link.properties.get("https://diaspora.org/ns/handle")
                }

    raise ValueError("The document does not contain a valid Diaspora profile-page link")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_data = json.loads(document)
        return {
            "subject": json_data["subject"],
            "aliases": [alias["value"] for alias in json_data["aliases"]],
            "links": [link["href"] for link in json_data["links"]],
        }
    except KeyError:
        pass

    try:
        xrd_data = ElementTree.fromstring(document)
        subject = xrd_data.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject").text
        aliases = [
            alias.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias").attrib["value"]
            for alias in xrd_data.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Aliases")
        ]
        links = [
            link.attrib["href"]
            for link in xrd_data.find("{http://docs.oasis-open.org/ns/xri/xrd-1.0}Links")
        ]
        return {
            "subject": subject,
            "aliases": aliases,
            "links": links,
        }
    except AttributeError:
        return None
    except ElementTree.ParseError:
        return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree

    try:
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        try:
            root = ElementTree.fromstring(document)
            data = {}
            for child in root:
                if child.tag == "jid":
                    data["jid"] = child.text
                elif child.tag == "link":
                    data["link"] = child.attrib["href"]
                else:
                    data[child.tag] = child.text
            return data
        except ElementTree.ParseError:
            raise ValueError("Invalid Diaspora webfinger document")

