def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        self._convert_main_args(values_dict)
    elif parser_name == "virsh":
        self._convert_virsh_args(values_dict)
    elif parser_name == "ospd":
        self._convert_ospd_args(values_dict)
    else:
        raise ValueError(f"Invalid parser name: {parser_name}")

def _convert_non_cli_args(self, parser_name, values_dict):
    try:
        for key, value in values_dict.items():
            if key in self.__parsers[parser_name]._arguments:
                try:
                    values_dict[key] = self.__parsers[parser_name]._arguments[key](value)
                except ValueError as e:
                    raise InvalidArgumentError(f"Invalid value for argument '{key}': {value}") from e
    except KeyError as e:
        raise NonExistentArgumentError(f"Argument '{key}' does not exist for command '{parser_name}'") from e

